<?php declare(strict_types=1); namespace App\Controllers; use App\Core\Controller; use App\Core\Session; use App\Services\LiquidityPoolService; use DomainException; final class LiquidityTeamController extends Controller{private LiquidityPoolService $s; public function __construct(){$this->s=new LiquidityPoolService();} public function loginForm():void{$this->view('liquidity.team.login');} public function login():void{try{$d=$this->s->loginTeam((string)$_POST['access_code'],(string)$_POST['login_code']);Session::set('liquidity_session_id',$d['session']['id']);Session::set('liquidity_team_id',$d['team']['id']);$this->redirectTo('/liquidity/team/dashboard');}catch(DomainException $e){Session::flash('error',$e->getMessage());$this->redirectTo('/liquidity/team/login');}} public function dashboard():void{$sid=(int)Session::get('liquidity_session_id',0);$this->view('liquidity.team.dashboard',['state'=>$this->s->getProjectorState($sid),'team'=>(new \App\Repositories\LiquidityTeamRepository())->findById((int)Session::get('liquidity_team_id',0))]);} public function submitAction():void{$this->s->submitTeamAction((int)Session::get('liquidity_session_id',0),(int)Session::get('liquidity_team_id',0),(string)$_POST['action_type'],(float)($_POST['quantity']??1));$this->redirectTo('/liquidity/team/dashboard');}}
